def activitySelection(activities):
    # activities: list of (start, end)
    activities.sort(key=lambda x: x[1])  # Sort by end time

    count = 0
    last_end = -float('inf')

    for start, end in activities:
        if start >= last_end:
            count += 1
            last_end = end

    return count  # O(n log n)

def fractionalKnapsack(items, capacity):
    # items: list of (value, weight)
    items.sort(key=lambda x: x[0]/x[1], reverse=True)

    total_value = 0
    for value, weight in items:
        if capacity >= weight:
            total_value += value
            capacity -= weight
        else:
            total_value += value * (capacity / weight)
            break

    return total_value  # O(n log n)

import heapq

def huffmanCoding(frequencies):
    heap = [[freq, char] for char, freq in frequencies.items()]
    heapq.heapify(heap)

    while len(heap) > 1:
        freq1, char1 = heapq.heappop(heap)
        freq2, char2 = heapq.heappop(heap)
        heapq.heappush(heap, [freq1 + freq2, char1 + char2])

    return heap[0]  # Huffman tree (as string)
